package com.optarena.tasktracker;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.jayway.jsonpath.JsonPath;
import com.optarena.tasktracker.repository.ProjectRepository;
import com.optarena.tasktracker.repository.TaskRepository;
import com.optarena.tasktracker.repository.UserRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

@SpringBootTest
@AutoConfigureMockMvc
class InactiveUserCascadeHiddenTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private UserRepository userRepository;

    @Autowired
    private ProjectRepository projectRepository;

    @Autowired
    private TaskRepository taskRepository;

    @BeforeEach
    void resetState() {
        userRepository.clear();
        projectRepository.clear();
        taskRepository.clear();
    }

    private int createUser(String username) throws Exception {
        String body = mockMvc.perform(post("/users")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"username\":\"" + username + "\",\"email\":\""
                                + username + "@example.com\"}"))
                .andReturn().getResponse().getContentAsString();
        return JsonPath.read(body, "$.id");
    }

    private int createProject(int ownerId) throws Exception {
        String body = mockMvc.perform(post("/projects")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"Mercury\",\"ownerId\":" + ownerId + "}"))
                .andReturn().getResponse().getContentAsString();
        return JsonPath.read(body, "$.id");
    }

    private void deactivate(int userId) throws Exception {
        mockMvc.perform(patch("/users/" + userId)
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"active\":false}"));
    }

    @Test
    void cannotAssignTaskToInactiveUserOnCreate() throws Exception {
        int userId = createUser("dev");
        int projectId = createProject(userId);
        deactivate(userId);

        mockMvc.perform(post("/tasks")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"A\",\"projectId\":" + projectId
                                + ",\"assigneeId\":" + userId + "}"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void cannotReassignTaskToInactiveUser() throws Exception {
        int userId = createUser("dev");
        int other = createUser("helper");
        int projectId = createProject(userId);
        String taskBody = mockMvc.perform(post("/tasks")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"A\",\"projectId\":" + projectId
                                + ",\"assigneeId\":" + other + "}"))
                .andReturn().getResponse().getContentAsString();
        int taskId = JsonPath.read(taskBody, "$.id");

        deactivate(userId);

        mockMvc.perform(patch("/tasks/" + taskId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"assigneeId\":" + userId + "}"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void cannotCreateProjectOwnedByInactiveUser() throws Exception {
        int userId = createUser("dev");
        deactivate(userId);

        mockMvc.perform(post("/projects")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"Venus\",\"ownerId\":" + userId + "}"))
                .andExpect(status().isBadRequest());
    }
}

